"""One-shot patch for GeoSphere station metadata preview/cache (0.6.3).

This script is branch-local, deterministic and fail-fast. It upgrades the
GeoSphere metadata model, adds an O(1) station capability index, and wires the
metadata preview into the existing Streamlit source UI without issuing data
requests for preview purposes.
"""
from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: Path, old: str, new: str, label: str) -> None:
    text = path.read_text(encoding="utf-8")
    if new in text:
        return
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one source anchor, found {count}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


def patch_geosphere() -> None:
    path = ROOT / "epw_climate_analyzer" / "geosphere.py"

    replace_once(
        path,
        '''@dataclass(frozen=True)\nclass GeoSphereStation:\n    station_id: str\n    name: str\n    latitude: float\n    longitude: float\n    elevation_m: float | None = None\n    state: str = ""\n    valid_from: str = ""\n    valid_to: str = ""\n''',
        '''@dataclass(frozen=True)\nclass GeoSphereStation:\n    station_id: str\n    name: str\n    latitude: float\n    longitude: float\n    elevation_m: float | None = None\n    state: str = ""\n    valid_from: str = ""\n    valid_to: str = ""\n    station_type: str = ""\n    is_active: bool | None = None\n    has_global_radiation: bool | None = None\n    has_sunshine: bool | None = None\n''',
        "GeoSphere station metadata fields",
    )

    replace_once(
        path,
        '''def _float_or_none(value: object) -> float | None:\n    if value in (None, ""):\n        return None\n    try:\n        result = float(value)\n    except (TypeError, ValueError):\n        return None\n    return result if math.isfinite(result) else None\n\n\ndef _station_coordinates''',
        '''def _float_or_none(value: object) -> float | None:\n    if value in (None, ""):\n        return None\n    try:\n        result = float(value)\n    except (TypeError, ValueError):\n        return None\n    return result if math.isfinite(result) else None\n\n\ndef _bool_or_none(value: object) -> bool | None:\n    """Return a provider Boolean without inventing truth for missing metadata."""\n    if isinstance(value, bool):\n        return value\n    if value in (0, 1):\n        return bool(value)\n    if isinstance(value, str):\n        normalized = value.strip().casefold()\n        if normalized in {"true", "yes", "1"}:\n            return True\n        if normalized in {"false", "no", "0"}:\n            return False\n    return None\n\n\ndef _station_coordinates''',
        "GeoSphere optional Boolean parser",
    )

    replace_once(
        path,
        '''                valid_from=str(_coalesce(record, "valid_from", "start", "start_time", default="")).strip(),\n                valid_to=str(_coalesce(record, "valid_to", "end", "end_time", default="")).strip(),\n            )\n''',
        '''                valid_from=str(_coalesce(record, "valid_from", "start", "start_time", default="")).strip(),\n                valid_to=str(_coalesce(record, "valid_to", "end", "end_time", default="")).strip(),\n                station_type=str(_coalesce(record, "type", "station_type", default="")).strip(),\n                is_active=_bool_or_none(record.get("is_active")),\n                has_global_radiation=_bool_or_none(record.get("has_global_radiation")),\n                has_sunshine=_bool_or_none(record.get("has_sunshine")),\n            )\n''',
        "GeoSphere station parser extended metadata",
    )

    anchor = '''    if not resolved:\n        raise ValueError("GeoSphere metadata expose none of the supported climate parameters.")\n    return resolved\n\n\ndef station_catalog(metadata: Mapping[str, Any]) -> pd.DataFrame:\n'''
    insert = '''    if not resolved:\n        raise ValueError("GeoSphere metadata expose none of the supported climate parameters.")\n    return resolved\n\n\nCAPABILITY_RESOURCE_SUPPORTED = "resource-supported"\nCAPABILITY_STATION_CONFIRMED = "station-confirmed"\nCAPABILITY_STATION_UNAVAILABLE = "station-unavailable"\n\n\ndef station_parameter_capability_index(metadata: Mapping[str, Any]) -> dict[str, dict[str, str]]:\n    """Return O(1) station -> provider-parameter capability lookups.\n\n    GeoSphere currently publishes the full resource parameter list plus a small\n    set of station-specific sensor flags.  Only an explicit station flag is\n    allowed to disable a parameter.  For fields without station-specific\n    metadata, the status remains ``resource-supported`` and actual observations\n    for the selected period are still verified after data loading.\n\n    In particular, ``has_global_radiation`` authoritatively qualifies ``cglo``.\n    No station-level flag for diffuse radiation is published, so ``chim`` is not\n    inferred from the global-radiation flag.\n    """\n    supported = supported_parameter_mapping(metadata)\n    base = {name: CAPABILITY_RESOURCE_SUPPORTED for name in supported}\n    result: dict[str, dict[str, str]] = {}\n    for record in _station_records(metadata):\n        station_id = str(_coalesce(record, "id", "station_id", "station", default="")).strip()\n        if not station_id:\n            continue\n        statuses = dict(base)\n        global_radiation = _bool_or_none(record.get("has_global_radiation"))\n        if "cglo" in statuses and global_radiation is not None:\n            statuses["cglo"] = (\n                CAPABILITY_STATION_CONFIRMED if global_radiation else CAPABILITY_STATION_UNAVAILABLE\n            )\n        result[station_id] = statuses\n    if not result:\n        raise ValueError("GeoSphere metadata contain no station capability index.")\n    return result\n\n\ndef station_parameter_capability_table(metadata: Mapping[str, Any], station_id: str) -> pd.DataFrame:\n    """Return a display-ready metadata capability table for one station.\n\n    ``Available`` means selectable from metadata, not guaranteed non-null data\n    for every timestamp. Selected-period coverage remains a loaded-data quality\n    concern and is intentionally not fabricated from station validity dates.\n    """\n    station_key = str(station_id).strip()\n    index = station_parameter_capability_index(metadata)\n    if station_key not in index:\n        raise KeyError(f"Unknown GeoSphere station id: {station_key}")\n    parameters = parse_parameters(metadata)\n    supported = supported_parameter_mapping(metadata)\n    statuses = index[station_key]\n    rows: list[dict[str, object]] = []\n    for provider_name, spec in supported.items():\n        parameter = parameters.get(provider_name)\n        status = statuses.get(provider_name, CAPABILITY_RESOURCE_SUPPORTED)\n        if status == CAPABILITY_STATION_CONFIRMED:\n            basis = "Station metadata confirms sensor"\n        elif status == CAPABILITY_STATION_UNAVAILABLE:\n            basis = "Station metadata reports unavailable"\n        else:\n            basis = "Resource metadata; period coverage checked after load"\n        rows.append(\n            {\n                "provider": provider_name,\n                "canonical": spec.canonical_name,\n                "variable": (parameter.long_name if parameter and parameter.long_name else spec.description or spec.canonical_name),\n                "unit": parameter.unit if parameter else "",\n                "status": status,\n                "available": status != CAPABILITY_STATION_UNAVAILABLE,\n                "basis": basis,\n            }\n        )\n    return pd.DataFrame(rows)\n\n\ndef station_catalog(metadata: Mapping[str, Any]) -> pd.DataFrame:\n'''
    replace_once(path, anchor, insert, "GeoSphere station capability index")


def patch_app() -> None:
    path = ROOT / "app.py"

    replace_once(
        path,
        '''@st.cache_data(show_spinner=False, ttl=3600)\ndef cached_geosphere_metadata() -> dict:\n    """Cache current GeoSphere metadata for one hour within a user session/runtime."""\n    from epw_climate_analyzer.geosphere import fetch_metadata\n\n    return fetch_metadata()\n''',
        '''GEOSPHERE_METADATA_CACHE_TTL_SECONDS = 18 * 60 * 60\n\n\n@st.cache_data(show_spinner=False, ttl=GEOSPHERE_METADATA_CACHE_TTL_SECONDS, max_entries=2)\ndef _cached_geosphere_metadata_bundle(resource_id: str) -> tuple:\n    """Cache GeoSphere metadata and its normalized station capability index.\n\n    The resource id is part of the Streamlit cache key so a future resource\n    migration cannot silently reuse a metadata snapshot from another dataset.\n    The cache contains metadata only; no measurement endpoint is called here.\n    """\n    from epw_climate_analyzer.geosphere import (\n        GEOSPHERE_RESOURCE_ID,\n        fetch_metadata,\n        parse_parameters,\n        parse_stations,\n        station_catalog,\n        station_parameter_capability_index,\n        supported_parameter_mapping,\n    )\n\n    if str(resource_id) != GEOSPHERE_RESOURCE_ID:\n        raise ValueError(f"Unsupported GeoSphere metadata resource: {resource_id}")\n    metadata = fetch_metadata()\n    return (\n        metadata,\n        supported_parameter_mapping(metadata),\n        parse_stations(metadata),\n        station_catalog(metadata),\n        station_parameter_capability_index(metadata),\n        parse_parameters(metadata),\n    )\n\n\ndef cached_geosphere_metadata_bundle() -> tuple:\n    """Return the current resource-keyed GeoSphere metadata bundle."""\n    from epw_climate_analyzer.geosphere import GEOSPHERE_RESOURCE_ID\n\n    return _cached_geosphere_metadata_bundle(GEOSPHERE_RESOURCE_ID)\n\n\ndef cached_geosphere_metadata() -> dict:\n    """Compatibility accessor for callers that only need raw metadata."""\n    return cached_geosphere_metadata_bundle()[0]\n''',
        "GeoSphere resource-aware metadata cache",
    )

    replace_once(
        path,
        '''    try:\n        metadata = cached_geosphere_metadata()\n        supported = supported_geosphere_parameter_mapping(metadata)\n        stations = parse_geosphere_stations(metadata)\n        catalog = geosphere_station_catalog(metadata)\n    except Exception as exc:\n''',
        '''    try:\n        metadata, supported, stations, catalog, capability_index, parameter_metadata = cached_geosphere_metadata_bundle()\n    except Exception as exc:\n''',
        "GeoSphere cached metadata bundle call",
    )

    replace_once(
        path,
        '''    map_groups = filtered[["station_id", "name", "state", "latitude", "longitude", "elevation_m"]].copy()\n    map_groups["station_group_id"] = map_groups["station_id"].astype(str)\n    map_groups["country"] = "Austria"\n''',
        '''    map_groups = filtered[[\n        "station_id", "name", "state", "latitude", "longitude", "elevation_m",\n        "valid_from", "valid_to", "station_type", "is_active", "has_global_radiation", "has_sunshine",\n    ]].copy()\n    map_groups["station_group_id"] = map_groups["station_id"].astype(str)\n\n    # Keep the shared Leaflet engine, but enrich only the GeoSphere marker label.\n    # Hover stays entirely client-side and therefore never triggers a metadata or\n    # measurement request. The station validity interval is shown as metadata,\n    # not as a claim of gap-free parameter coverage.\n    def geosphere_hover_name(row: pd.Series) -> str:\n        elevation = f"{float(row['elevation_m']):.0f} m" if pd.notna(row.get("elevation_m")) else "elevation unknown"\n        valid_from = str(row.get("valid_from", "")).split("T", 1)[0] or "unknown"\n        valid_to = str(row.get("valid_to", "")).split("T", 1)[0] or "unknown"\n        return f"{row['name']} · ID {row['station_id']} · {elevation} · validity {valid_from} → {valid_to}"\n\n    map_groups["name"] = map_groups.apply(geosphere_hover_name, axis=1)\n    map_groups["country"] = ""\n''',
        "GeoSphere rich client-side marker hover",
    )

    replace_once(
        path,
        '''        st.dataframe(\n            pd.DataFrame(\n                {\n                    "Field": ["Station", "ID", "Region", "Latitude", "Longitude", "Elevation", "Provider validity"],\n                    "Value": [\n                        station.name, station.station_id, station.state,\n                        f"{station.latitude:.5f}", f"{station.longitude:.5f}",\n                        f"{station.elevation_m:.0f} m" if station.elevation_m is not None else "",\n                        f"{station.valid_from or 'unknown'} … {station.valid_to or 'unknown'}",\n                    ],\n                }\n            ),\n            hide_index=True,\n            use_container_width=True,\n        )\n        st.markdown("#### Manual station selection")\n''',
        '''        def yes_no_unknown(value: bool | None) -> str:\n            return "Yes" if value is True else ("No" if value is False else "Unknown")\n\n        st.dataframe(\n            pd.DataFrame(\n                {\n                    "Field": [\n                        "Station", "ID", "Region", "Latitude", "Longitude", "Elevation",\n                        "Station type", "Active", "Global radiation flag", "Sunshine flag", "Provider validity",\n                    ],\n                    "Value": [\n                        station.name, station.station_id, station.state,\n                        f"{station.latitude:.5f}", f"{station.longitude:.5f}",\n                        f"{station.elevation_m:.0f} m" if station.elevation_m is not None else "",\n                        station.station_type or "unknown", yes_no_unknown(station.is_active),\n                        yes_no_unknown(station.has_global_radiation), yes_no_unknown(station.has_sunshine),\n                        f"{station.valid_from or 'unknown'} … {station.valid_to or 'unknown'}",\n                    ],\n                }\n            ),\n            hide_index=True,\n            use_container_width=True,\n        )\n\n        station_capabilities = capability_index.get(selected_id, {})\n        preview_rows = []\n        for name, spec in supported.items():\n            parameter = parameter_metadata.get(name)\n            status = station_capabilities.get(name, "resource-supported")\n            availability = (\n                "Confirmed by station metadata" if status == "station-confirmed"\n                else ("Unavailable at station" if status == "station-unavailable" else "Resource-supported")\n            )\n            preview_rows.append(\n                {\n                    "Variable": parameter.long_name if parameter and parameter.long_name else spec.description or spec.canonical_name,\n                    "Provider": name,\n                    "Unit": parameter.unit if parameter else "",\n                    "Availability": availability,\n                }\n            )\n        with st.expander("Measured-variable metadata", expanded=False):\n            st.dataframe(pd.DataFrame(preview_rows), hide_index=True, use_container_width=True)\n            st.caption(\n                "GeoSphere publishes an explicit station-level global-radiation flag. Other listed variables are supported "\n                "by the resource metadata; their actual numeric coverage for the selected period is verified only after load. "\n                "No per-parameter validity dates are inferred."
            )\n\n        st.markdown("#### Manual station selection")\n''',
        "GeoSphere selected-station metadata preview",
    )

    replace_once(
        path,
        '''    variable_rows = pd.DataFrame(\n        [\n            {\n                "Selected": True,\n                "Measured variable": spec.description or spec.canonical_name,\n                "Provider": name,\n                "Canonical field": spec.canonical_name,\n            }\n            for name, spec in supported.items()\n        ]\n    )\n    edited_variables = st.data_editor(\n        variable_rows,\n        hide_index=True,\n        use_container_width=True,\n        num_rows="fixed",\n        disabled=["Measured variable", "Provider", "Canonical field"],\n        column_config={\n            "Selected": st.column_config.CheckboxColumn("Load", width="small"),\n            "Measured variable": st.column_config.TextColumn("Measured variable", width="medium"),\n            "Provider": st.column_config.TextColumn("Provider parameter", width="small"),\n            "Canonical field": st.column_config.TextColumn("Canonical field", width="large"),\n        },\n        key="geosphere_variable_editor",\n    )\n''',
        '''    station_capabilities = capability_index.get(selected_id, {})\n    selectable_supported = {\n        name: spec\n        for name, spec in supported.items()\n        if station_capabilities.get(name, "resource-supported") != "station-unavailable"\n    }\n    unavailable_names = [\n        name for name in supported\n        if station_capabilities.get(name, "resource-supported") == "station-unavailable"\n    ]\n    if unavailable_names:\n        st.info(\n            "Not selectable because station metadata reports the sensor unavailable: "\n            + ", ".join(unavailable_names)\n            + "."
        )\n    if not selectable_supported:\n        st.warning("No supported GeoSphere variables are selectable for this station according to metadata.")\n        return\n\n    variable_rows = pd.DataFrame(\n        [\n            {\n                "Selected": True,\n                "Measured variable": (\n                    parameter_metadata[name].long_name\n                    if name in parameter_metadata and parameter_metadata[name].long_name\n                    else spec.description or spec.canonical_name\n                ),\n                "Provider": name,\n                "Unit": parameter_metadata[name].unit if name in parameter_metadata else "",\n                "Availability": (\n                    "Station-confirmed"\n                    if station_capabilities.get(name) == "station-confirmed"\n                    else "Resource-supported"\n                ),\n                "Canonical field": spec.canonical_name,\n            }\n            for name, spec in selectable_supported.items()\n        ]\n    )\n    edited_variables = st.data_editor(\n        variable_rows,\n        hide_index=True,\n        use_container_width=True,\n        num_rows="fixed",\n        disabled=["Measured variable", "Provider", "Unit", "Availability", "Canonical field"],\n        column_config={\n            "Selected": st.column_config.CheckboxColumn("Load", width="small"),\n            "Measured variable": st.column_config.TextColumn("Measured variable", width="medium"),\n            "Provider": st.column_config.TextColumn("Provider parameter", width="small"),\n            "Unit": st.column_config.TextColumn("Unit", width="small"),\n            "Availability": st.column_config.TextColumn("Metadata availability", width="medium"),\n            "Canonical field": st.column_config.TextColumn("Canonical field", width="large"),\n        },\n        key="geosphere_variable_editor",\n    )\n''',
        "GeoSphere metadata-qualified variable editor",
    )


def create_tests() -> None:
    path = ROOT / "tests" / "test_geosphere_metadata_preview_cache_0_6_3.py"
    if path.exists():
        return
    path.write_text('''from __future__ import annotations\n\nfrom pathlib import Path\nimport unittest\n\nfrom epw_climate_analyzer.geosphere import (\n    CAPABILITY_RESOURCE_SUPPORTED,\n    CAPABILITY_STATION_CONFIRMED,\n    CAPABILITY_STATION_UNAVAILABLE,\n    parse_stations,\n    station_parameter_capability_index,\n    station_parameter_capability_table,\n)\n\n\nPARAMETERS = [\n    {"name": "tl", "long_name": "Lufttemperatur 2m", "unit": "°C", "description": ""},\n    {"name": "rf", "long_name": "Relative Feuchte", "unit": "%", "description": ""},\n    {"name": "cglo", "long_name": "Globalstrahlung Mittelwert", "unit": "W/m²", "description": ""},\n    {"name": "chim", "long_name": "Himmelsstrahlung Mittelwert", "unit": "W/m²", "description": ""},\n]\n\nMETADATA = {\n    "parameters": PARAMETERS,\n    "stations": [\n        {\n            "id": 1, "name": "Aflenz", "state": "Steiermark", "altitude": 783.2,\n            "lat": 47.54594, "lon": 15.24069, "valid_from": "1983-05-01T00:00:00+00:00",\n            "valid_to": "2100-12-31T00:00:00+00:00", "type": "COMBINED", "is_active": True,\n            "has_global_radiation": True, "has_sunshine": True,\n        },\n        {\n            "id": 2, "name": "NoRadiation", "state": "Test", "altitude": 500.0,\n            "lat": 47.0, "lon": 14.0, "valid_from": "2000-01-01T00:00:00+00:00",\n            "valid_to": "2100-12-31T00:00:00+00:00", "type": "CLIMATE", "is_active": False,\n            "has_global_radiation": False, "has_sunshine": False,\n        },\n    ],\n}\n\n\nclass GeoSphereMetadataCapabilityTests(unittest.TestCase):\n    def test_station_metadata_fields_are_preserved(self) -> None:\n        stations = parse_stations(METADATA)\n        self.assertEqual(stations[0].station_type, "COMBINED")\n        self.assertIs(stations[0].is_active, True)\n        self.assertIs(stations[0].has_global_radiation, True)\n        self.assertIs(stations[0].has_sunshine, True)\n\n    def test_capability_index_is_station_keyed_and_conservative(self) -> None:\n        index = station_parameter_capability_index(METADATA)\n        self.assertEqual(index["1"]["cglo"], CAPABILITY_STATION_CONFIRMED)\n        self.assertEqual(index["2"]["cglo"], CAPABILITY_STATION_UNAVAILABLE)\n        self.assertEqual(index["2"]["tl"], CAPABILITY_RESOURCE_SUPPORTED)\n        # No station-level diffuse-radiation flag exists; do not infer chim from cglo.\n        self.assertEqual(index["2"]["chim"], CAPABILITY_RESOURCE_SUPPORTED)\n\n    def test_capability_table_disables_only_authoritative_station_unavailability(self) -> None:\n        table = station_parameter_capability_table(METADATA, "2").set_index("provider")\n        self.assertFalse(bool(table.loc["cglo", "available"]))\n        self.assertTrue(bool(table.loc["chim", "available"]))\n        self.assertIn("station metadata", str(table.loc["cglo", "basis"]).lower())\n        self.assertIn("period coverage", str(table.loc["tl", "basis"]).lower())\n\n\nclass GeoSphereMetadataPreviewUiContractTests(unittest.TestCase):\n    @classmethod\n    def setUpClass(cls) -> None:\n        root = Path(__file__).resolve().parents[1]\n        cls.source = (root / "app.py").read_text(encoding="utf-8")\n\n    def test_metadata_cache_is_resource_keyed_and_long_lived(self) -> None:\n        self.assertIn("GEOSPHERE_METADATA_CACHE_TTL_SECONDS = 18 * 60 * 60", self.source)\n        self.assertIn("def _cached_geosphere_metadata_bundle(resource_id: str)", self.source)\n        self.assertIn("station_parameter_capability_index(metadata)", self.source)\n        self.assertIn("return _cached_geosphere_metadata_bundle(GEOSPHERE_RESOURCE_ID)", self.source)\n\n    def test_preview_does_not_issue_measurement_request(self) -> None:\n        preview_pos = self.source.index('with st.expander("Measured-variable metadata"')\n        load_button_pos = self.source.index('if st.button("Load measured GeoSphere interval"')\n        fetch_pos = self.source.index("dataset = fetch_geosphere_station_dataset(")\n        self.assertLess(preview_pos, load_button_pos)\n        self.assertGreater(fetch_pos, load_button_pos)\n\n    def test_unavailable_station_capability_is_not_in_checkbox_source(self) -> None:\n        self.assertIn("selectable_supported = {", self.source)\n        self.assertIn('!= "station-unavailable"', self.source)\n        self.assertIn('st.column_config.CheckboxColumn("Load"', self.source)\n        self.assertNotIn('key="geosphere_provider_parameters"', self.source)\n\n    def test_map_hover_contains_metadata_without_changing_map_engine(self) -> None:\n        self.assertIn("def geosphere_hover_name", self.source)\n        self.assertIn("validity {valid_from} → {valid_to}", self.source)\n        self.assertIn("station_catalog_persistent_map_layers(", self.source)\n        self.assertIn('returned_objects=["last_object_clicked_tooltip"]', self.source)\n\n    def test_ui_explains_station_vs_resource_level_capability(self) -> None:\n        self.assertIn("No per-parameter validity dates are inferred.", self.source)\n        self.assertIn("actual numeric coverage for the selected period is verified only after load", self.source)\n\n\nif __name__ == "__main__":\n    unittest.main()\n''', encoding="utf-8")


def main() -> None:
    patch_geosphere()
    patch_app()
    create_tests()


if __name__ == "__main__":
    main()
